// Two-factor authentication screens (Supabase Auth TOTP). No custom crypto: the secret and QR code are
// generated by Supabase; we only show them and send the 6-digit code back.
import { useEffect, useState } from 'react';
import { useSettings } from '../context/SettingsContext.jsx';
import { useAsync } from '../lib/hooks.js';
import { Async, Field, Logo } from '../components/ui.jsx';
import { errorKey } from '../lib/supabase.js';
import { useAdmin } from './context.js';
import {
  listRoles, mfaFactors, mfaEnroll, mfaUnenroll, mfaVerify, mfaStatus, setMfaEnforcement, setRoleRequiresMfa, signOut,
} from '../services/admin.js';

const CODE_RE = /^\d{6}$/;

// Step 2 of sign-in: a verified factor exists but this session is still aal1.
export function MfaChallenge({ onDone }) {
  const { t } = useSettings();
  const [code, setCode] = useState('');
  const [err, setErr] = useState(null);
  const [busy, setBusy] = useState(false);
  const submit = async (e) => {
    e.preventDefault();
    if (!CODE_RE.test(code.replace(/\s/g, ''))) { setErr(t('err.mfa_bad_code')); return; }
    setBusy(true); setErr(null);
    try {
      const { totp } = await mfaFactors();
      if (!totp?.length) throw new Error('no_factor');
      await mfaVerify(totp[0].id, code);
      onDone();
    } catch (e2) { setErr(t(errorKey(e2))); setCode(''); } finally { setBusy(false); }
  };
  return (
    <main className="container main login">
      <form onSubmit={submit} className="admin-form">
        <Logo /><h1>{t('mfa.challengeTitle')}</h1>
        <p className="muted">{t('mfa.challengeHelp')}</p>
        <Field label={t('mfa.code')} htmlFor="mfa-code">
          <input id="mfa-code" inputMode="numeric" autoComplete="one-time-code" dir="ltr" maxLength={7} value={code}
            onChange={(e) => setCode(e.target.value)} aria-invalid={!!err} required autoFocus />
        </Field>
        {err && <p className="bad" role="alert">{err}</p>}
        <button className="btn btn-primary btn-block" disabled={busy}>{busy ? t('common.loading') : t('mfa.verify')}</button>
        <p><button type="button" className="btn btn-ghost" onClick={signOut}>{t('admin.signout')}</button></p>
        <p className="muted">{t('mfa.lostHint')}</p>
      </form>
    </main>
  );
}

// Enrollment: QR code + manual secret + confirmation code. Used when MFA is required (forced) and from Security.
export function MfaEnroll({ forced, onDone, onCancel }) {
  const { t } = useSettings();
  const [step, setStep] = useState({ busy: false, factor: null, err: null });
  const [code, setCode] = useState('');
  const start = async () => {
    setStep({ busy: true, factor: null, err: null });
    try {
      // Remove abandoned (unverified) attempts first, otherwise Supabase rejects a repeated friendly name.
      const { all } = await mfaFactors();
      for (const f of (all || []).filter((x) => x.status === 'unverified')) await mfaUnenroll(f.id).catch(() => {});
      const f = await mfaEnroll(`Stoph Shop ${new Date().toISOString().slice(0, 10)}`);
      setStep({ busy: false, factor: f, err: null });
    } catch (e) { setStep({ busy: false, factor: null, err: t(errorKey(e)) }); }
  };
  const confirm = async (e) => {
    e.preventDefault();
    if (!CODE_RE.test(code.replace(/\s/g, ''))) { setStep({ ...step, err: t('err.mfa_bad_code') }); return; }
    setStep({ ...step, busy: true, err: null });
    try { await mfaVerify(step.factor.id, code); onDone(); } catch (e2) { setStep({ ...step, busy: false, err: t(errorKey(e2)) }); setCode(''); }
  };
  const f = step.factor;
  return (
    <main className={forced ? 'container main login' : ''}>
      <section className="admin-form">
        {forced && <Logo />}
        <h1>{t('mfa.enrollTitle')}</h1>
        {forced && <p className="bad" role="alert">{t('mfa.forced')}</p>}
        <ol className="mfa-steps">
          <li>{t('mfa.step1')}</li><li>{t('mfa.step2')}</li><li>{t('mfa.step3')}</li>
        </ol>
        {!f && <button className="btn btn-primary" onClick={start} disabled={step.busy}>{step.busy ? t('common.loading') : t('mfa.start')}</button>}
        {f && (
          <form onSubmit={confirm}>
            {/* qr_code is an SVG data: URL generated by Supabase */}
            <img className="mfa-qr" src={f.totp.qr_code} alt={t('mfa.qrAlt')} width="200" height="200" />
            <p className="muted">{t('mfa.manual')}</p>
            <p><code dir="ltr" className="code">{f.totp.secret}</code></p>
            <Field label={t('mfa.code')} htmlFor="enroll-code">
              <input id="enroll-code" inputMode="numeric" autoComplete="one-time-code" dir="ltr" maxLength={7} value={code} onChange={(e) => setCode(e.target.value)} required />
            </Field>
            <button className="btn btn-primary" disabled={step.busy}>{t('mfa.confirm')}</button>
          </form>
        )}
        {step.err && <p className="bad" role="alert">{step.err}</p>}
        <p className="muted">{t('mfa.saveSecret')}</p>
        <div className="row">
          {!forced && onCancel && <button className="btn btn-ghost" onClick={onCancel}>{t('common.cancel')}</button>}
          {forced && <button className="btn btn-ghost" onClick={signOut}>{t('admin.signout')}</button>}
        </div>
      </section>
    </main>
  );
}

// /admin/security — own factors for everyone; enforcement switch + per-role requirement for the owner.
export function Security() {
  const { t } = useSettings();
  const { isOwner } = useAdmin();
  const factors = useAsync(mfaFactors, []);
  const status = useAsync(mfaStatus, []);
  const [adding, setAdding] = useState(false);
  const [msg, setMsg] = useState(null);
  const run = async (fn) => { setMsg(null); try { await fn(); factors.reload(); status.reload(); } catch (e) { setMsg(t(errorKey(e))); } };

  return (
    <>
      <h1>{t('mfa.title')}</h1>
      {msg && <p className="bad" role="alert">{msg}</p>}
      <Async state={factors}>
        {(f) => (
          <section>
            <h2>{t('mfa.yourFactors')}</h2>
            {adding ? <MfaEnroll onDone={() => { setAdding(false); factors.reload(); status.reload(); }} onCancel={() => setAdding(false)} /> : (
              <>
                {f.totp.length === 0 ? <p className="state">{t('mfa.none')}</p> : (
                  <ul>{f.totp.map((x) => (
                    <li key={x.id}>{x.friendly_name || 'TOTP'} <small className="muted">({new Date(x.created_at).toLocaleDateString()})</small>{' '}
                      <button className="btn btn-ghost" onClick={() => window.confirm(t('mfa.removeConfirm')) && run(() => mfaUnenroll(x.id))}>{t('common.delete')}</button></li>))}</ul>
                )}
                <button className="btn" onClick={() => setAdding(true)}>{t('mfa.add')}</button>
                <p className="muted">{t('mfa.removeNote')}</p>
              </>
            )}
          </section>
        )}
      </Async>
      {isOwner && <OwnerMfaControls status={status} run={run} />}
    </>
  );
}

function OwnerMfaControls({ status, run }) {
  const { t } = useSettings();
  const roles = useAsync(listRoles, []);
  return (
    <section>
      <h2>{t('mfa.enforcement')}</h2>
      <Async state={status}>
        {(s) => (
          <>
            <p>{s.enforced ? t('mfa.enforcedOn') : t('mfa.enforcedOff')} — {t('mfa.thisSession')}: <strong dir="ltr">{s.aal || '—'}</strong></p>
            <p className="muted">{t('mfa.enforceWarn')}</p>
            <button className="btn btn-primary" disabled={!s.enforced && s.aal !== 'aal2'}
              onClick={() => run(() => setMfaEnforcement(!s.enforced))}>{s.enforced ? t('mfa.turnOff') : t('mfa.turnOn')}</button>
            {!s.enforced && s.aal !== 'aal2' && <p className="muted">{t('mfa.needAal2')}</p>}
          </>
        )}
      </Async>
      <h3>{t('mfa.rolesTitle')}</h3>
      <Async state={roles}>
        {(r) => (
          <ul className="checks">{r.roles.map((role) => (
            <li key={role.id}><label><input type="checkbox" checked={!!role.requires_mfa} disabled={role.key === 'owner'}
              onChange={(e) => run(async () => { await setRoleRequiresMfa(role.id, e.target.checked); roles.reload(); })} /> {role.name} <small className="muted" dir="ltr">({role.key})</small></label></li>))}</ul>
        )}
      </Async>
    </section>
  );
}
